void ShowError(const wchar_t* title,HRESULT hr){ wchar_t b[512]; swprintf_s(b,L"%s\n\nHRESULT: 0x%08X",title,(unsigned)hr); MessageBoxW(g_mainWindow,b,L"Pockie Clicker",MB_ICONERROR|MB_OK); }
void PostUiMessage(const wchar_t* m){ if(g_webView) g_webView->PostWebMessageAsString(m); }
void PostCount(){ wchar_t b[64]; swprintf_s(b,L"count:%zu",g_events.size()/2); PostUiMessage(b); }
bool IsWebViewPoint(POINT p){ return p.x>=0&&p.y>=0&&p.x<kViewportWidth&&p.y<kViewportHeight; }
bool IsRecorderUiPoint(POINT p){ bool h=p.x>=kViewportWidth-kHamburgerSize-12&&p.x<kViewportWidth-8&&p.y>=8&&p.y<72; bool panel=g_sidebarExpanded&&p.x>=kViewportWidth-kSidebarWidth; return h||panel; }
COREWEBVIEW2_MOUSE_EVENT_VIRTUAL_KEYS MouseKeysFromWParam(WPARAM w){ return (COREWEBVIEW2_MOUSE_EVENT_VIRTUAL_KEYS)GET_KEYSTATE_WPARAM(w); }
bool IsRecordableButtonMessage(UINT m){ return m==WM_LBUTTONDOWN||m==WM_LBUTTONUP||m==WM_LBUTTONDBLCLK||m==WM_RBUTTONDOWN||m==WM_RBUTTONUP||m==WM_RBUTTONDBLCLK; }
void StopAll(bool notify=true){ g_recording=false; g_playing=false; g_playIndex=0; if(g_mainWindow) KillTimer(g_mainWindow,kPlaybackTimerId); if(notify){PostUiMessage(L"mode:idle");PostCount();} }
void StartRecording(){ StopAll(false); g_events.clear(); g_recordStart=std::chrono::steady_clock::now(); g_recording=true; PostUiMessage(L"mode:recording"); PostCount(); }
void StartPlayback(){ if(!g_compositionController){PostUiMessage(L"error:WebView2 is not ready yet");return;} if(g_events.empty()){PostUiMessage(L"error:Nothing has been recorded yet");return;} StopAll(false); g_playing=true; g_playIndex=0; g_playStart=std::chrono::steady_clock::now(); SetTimer(g_mainWindow,kPlaybackTimerId,kPlaybackTickMs,nullptr); PostUiMessage(L"mode:playing"); }
void ClearRecording(){ StopAll(false); g_events.clear(); PostUiMessage(L"mode:idle"); PostCount(); }
void RecordMouseEvent(UINT m,WPARAM w,POINT p){ if(!g_recording||!IsRecordableButtonMessage(m)||IsRecorderUiPoint(p))return; auto now=std::chrono::steady_clock::now(); auto elapsed=std::chrono::duration_cast<std::chrono::milliseconds>(now-g_recordStart).count(); RecordedMouseEvent e; e.timeMs=(uint64_t)std::max<int64_t>(0,elapsed); e.kind=(COREWEBVIEW2_MOUSE_EVENT_KIND)m; e.keys=MouseKeysFromWParam(w); e.point=p; g_events.push_back(e); PostCount(); }
HRESULT SendToWebView(UINT m,WPARAM w,LPARAM l){ if(!g_compositionController)return E_PENDING; POINT p{GET_X_LPARAM(l),GET_Y_LPARAM(l)}; bool inside=IsWebViewPoint(p); if(!(inside||m==WM_MOUSELEAVE||g_capturingMouse))return S_FALSE; DWORD data=0; switch(m){case WM_MOUSEWHEEL:case WM_MOUSEHWHEEL:data=(DWORD)GET_WHEEL_DELTA_WPARAM(w);break;case WM_XBUTTONDBLCLK:case WM_XBUTTONDOWN:case WM_XBUTTONUP:data=GET_XBUTTON_WPARAM(w);break;case WM_MOUSEMOVE:if(!g_trackingMouse){TRACKMOUSEEVENT t{sizeof(t),TME_LEAVE,g_mainWindow,0};TrackMouseEvent(&t);g_trackingMouse=true;}break;case WM_MOUSELEAVE:g_trackingMouse=false;p={0,0};break;} if(m==WM_LBUTTONDOWN||m==WM_RBUTTONDOWN||m==WM_MBUTTONDOWN||m==WM_XBUTTONDOWN){if(inside&&GetCapture()!=g_mainWindow){SetCapture(g_mainWindow);g_capturingMouse=true;} if(g_controller)g_controller->MoveFocus(COREWEBVIEW2_MOVE_FOCUS_REASON_PROGRAMMATIC);} else if(m==WM_LBUTTONUP||m==WM_RBUTTONUP||m==WM_MBUTTONUP||m==WM_XBUTTONUP){if(GetCapture()==g_mainWindow){ReleaseCapture();g_capturingMouse=false;}} if(m!=WM_MOUSELEAVE)RecordMouseEvent(m,w,p); return g_compositionController->SendMouseInput((COREWEBVIEW2_MOUSE_EVENT_KIND)m,MouseKeysFromWParam(w),data,p); }
void PlaybackTick(){ if(!g_playing||!g_compositionController)return; auto now=std::chrono::steady_clock::now(); auto elapsed=(uint64_t)std::chrono::duration_cast<std::chrono::milliseconds>(now-g_playStart).count(); while(g_playIndex<g_events.size()&&g_events[g_playIndex].timeMs<=elapsed){auto&e=g_events[g_playIndex];g_compositionController->SendMouseInput(COREWEBVIEW2_MOUSE_EVENT_KIND_MOVE,COREWEBVIEW2_MOUSE_EVENT_VIRTUAL_KEYS_NONE,0,e.point);g_compositionController->SendMouseInput(e.kind,e.keys,0,e.point);++g_playIndex;} if(g_playIndex>=g_events.size())StopAll(true); }
std::wstring GetLocalAppDataWebViewFolder(){ wchar_t p[MAX_PATH]{}; DWORD n=GetEnvironmentVariableW(L"LOCALAPPDATA",p,MAX_PATH); if(n==0||n>=MAX_PATH)return L"PockieClickerPOC.WebView2"; std::wstring f(p); f+=L"\\PockieClickerPOC\\WebView2"; return f; }
HRESULT BuildCompositionTree(){ HRESULT hr=DCompositionCreateDevice(nullptr,IID_PPV_ARGS(&g_dcompDevice));if(FAILED(hr))return hr;hr=g_dcompDevice->CreateTargetForHwnd(g_mainWindow,FALSE,&g_dcompTarget);if(FAILED(hr))return hr;hr=g_dcompDevice->CreateVisual(&g_dcompRootVisual);if(FAILED(hr))return hr;hr=g_dcompTarget->SetRoot(g_dcompRootVisual.Get());if(FAILED(hr))return hr;hr=g_dcompDevice->CreateVisual(&g_dcompWebViewVisual);if(FAILED(hr))return hr;hr=g_dcompRootVisual->AddVisual(g_dcompWebViewVisual.Get(),TRUE,nullptr);if(FAILED(hr))return hr;return g_dcompDevice->Commit(); }
