void InstallSidebarAndNavigate(){ if(!g_webView)return; HRESULT hr=g_webView->AddScriptToExecuteOnDocumentCreated(kSidebarScript,Callback<ICoreWebView2AddScriptToExecuteOnDocumentCreatedCompletedHandler>([](HRESULT e,LPCWSTR)->HRESULT{if(FAILED(e))ShowError(L"Could not install the in-WebView recorder sidebar.",e);if(g_webView)g_webView->Navigate(kGameUrl);return S_OK;}).Get()); if(FAILED(hr)){ShowError(L"Sidebar script registration failed.",hr);g_webView->Navigate(kGameUrl);} }
void HandleWebMessage(ICoreWebView2WebMessageReceivedEventArgs* a){LPWSTR raw=nullptr;if(FAILED(a->TryGetWebMessageAsString(&raw))||!raw)return;std::wstring t(raw);CoTaskMemFree(raw);if(t==L"record")StartRecording();else if(t==L"stop")StopAll(true);else if(t==L"play")StartPlayback();else if(t==L"clear")ClearRecording();else if(t==L"ui:expanded")g_sidebarExpanded=true;else if(t==L"ui:collapsed")g_sidebarExpanded=false;else if(t==L"ready"){PostUiMessage(g_recording?L"mode:recording":(g_playing?L"mode:playing":L"mode:idle"));PostCount();}}
